import {api} from '../../api/client';import {Button,Card} from '../../components/Ui';
/** Download a statement generated by the live backend. */ export default function StatementsPage(){const download=async()=>{const r=await api.get('/statements/csv',{responseType:'blob'});const u=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=u;a.download='statement.csv';a.click();URL.revokeObjectURL(u)};return <Card><small>DOCUMENT CENTRE</small><h2>Account statement</h2><p>Download your recent activity as a CSV file.</p><Button onClick={download}>Download CSV statement</Button></Card>}
